CREATE TRIGGER tasks_obligation_id_insert BEFORE INSERT ON tasks WHEN json_extract(NEW.data,'$.obligation_id') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM obligations parent WHERE parent.id=json_extract(NEW.data,'$.obligation_id') AND (json_extract(NEW.data,'$.project_id') IS NULL OR json_extract(parent.data,'$.project_id')=json_extract(NEW.data,'$.project_id'))) BEGIN SELECT RAISE(ABORT,'Invalid reference ownership'); END;
